def transform(grid):
    h, w = len(grid), len(grid[0])

    # The uniform divider separates the patterned input from the panel
    # whose non-background cells are to be highlighted.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panel = [line[:] for line in grid[r + 1:]]
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                panel = [row[c + 1:] for row in grid]
                break

    from collections import Counter
    counts = Counter(x for row in panel for x in row)
    background = counts.most_common(1)[0][0]
    return [[background if x == background else 3 for x in row] for row in panel]
